input.function:
() => {
  const el = document.querySelector('[aria-label="Incident report content"]') || document.activeElement;
  function describe(e) {
    if (!e) return null;
    return {tag: e.tagName, contentEditable: e.contentEditable, role: e.getAttribute('role'), classes: e.className};
  }
  const region = document.querySelector('[aria-label="Incident report content"]');
  return describe(region);
}

