async (page) => {
  const canvas = await page.$('#editor-canvas');
  // Caret 1: normal click at start of "Timeline" (Ln5, Col1)
  await canvas.click({ position: { x: 0, y: 90 } });
  let status = await page.$eval('main', el => el.innerText);
