  await canvas.click({ position: { x: 0, y: 230 } });
  await page.keyboard.up('Control');
  status = await page.$eval('main', el => el.innerText);
  const s2 = status.split('\n').filter(l => l.startsWith('Ln') || l.includes('caret'));

  // Caret 3: Ctrl+click at start of "Action items" (Ln17, Col1)
  await page.keyboard.down('Control');
  await canvas.click({ position: { x: 0, y: 330 } });
